// مساعد كراسة الشروط والمواصفات — معهد البحوث والدراسات
// Cloudflare Worker: serves both pages and proxies AI requests to the Claude API.
// Settings > Variables and Secrets:
//   ANTHROPIC_API_KEY (secret)  Claude API key — never sent to the browser
//   ACCESS_CODE       (secret)  shared access code users enter once (replace with SSO in production)
//   MODEL             (optional) default: claude-sonnet-5-5
//   ANTHROPIC_BASE_URL (optional) e.g. an approved gateway; default https://api.anthropic.com
// Generated by build/build.mjs — edit worker.template.js, not worker.js.
const HTML_PM = __HTML_PM__;
const HTML_CM = __HTML_CM__;
const SEC = { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "x-frame-options": "DENY", "referrer-policy": "no-referrer", "x-content-type-options": "nosniff" };
const json = (o, status = 200) => new Response(JSON.stringify(o), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/api/claude") {
      if (request.method !== "POST") return json({ error: "method_not_allowed" }, 405);
      if (!env.ACCESS_CODE || request.headers.get("x-access-code") !== env.ACCESS_CODE) return json({ error: "unauthorized" }, 401);
      if (!env.ANTHROPIC_API_KEY) return json({ error: "server_not_configured" }, 500);
      let body; try { body = await request.json(); } catch { return json({ error: "bad_request" }, 400); }
      const messages = (Array.isArray(body.messages) ? body.messages : [])
        .filter(m => m && (m.role === "user" || m.role === "assistant") && typeof m.content === "string" && m.content.trim()).slice(-20);
      if (!messages.length || messages[0].role !== "user" || messages[messages.length - 1].role !== "user") return json({ error: "bad_request" }, 400);
      if (JSON.stringify(messages).length > 400000) return json({ error: "too_large" }, 413);
      const r = await fetch((env.ANTHROPIC_BASE_URL || "https://api.anthropic.com").replace(/\/$/,"") + "/v1/messages", {
        method: "POST",
        headers: { "x-api-key": env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "content-type": "application/json" },
        body: JSON.stringify({ model: env.MODEL || "claude-sonnet-5-5", max_tokens: 12000, messages })
      });
      let j = {}; try { j = await r.json(); } catch {}
      if (!r.ok) return json({ error: (j.error && j.error.type) || "upstream_error" }, (r.status === 429 || r.status === 529) ? 429 : 502);
      return json({ text: (j.content || []).filter(c => c.type === "text").map(c => c.text).join(""), stop_reason: j.stop_reason });
    }
    if (url.pathname === "/contracts") return new Response(HTML_CM, { headers: SEC });
    if (url.pathname === "/" || url.pathname === "/index.html") return new Response(HTML_PM, { headers: SEC });
    return new Response("Not found", { status: 404 });
  }
};
